const REAL_DATA = new RegExp(`\\b${VERB}[^.\\n]{0,100}${REAL}|${REAL}[^.\\n]{0,100}(?:verif\\w*|scan\\w*|audit\\w*|inspect\\w*|confirm\\w*|check\\w*)`, 'i');
if (!nonNit.some((r) => REAL_DATA.test(r.action))) miss.push('real-data-verification');

done();
